create table FM_BRANCH_HOLIDAY (BRANCH VARCHAR(30) not null  ,HOLIDAY_TYPE VARCHAR(1) not null  ,HOLIDAY_DESC VARCHAR(50) null  ,HOLIDAY_DATE TIMESTAMP(3) not null  ,WORKING_HOLIDAY VARCHAR(1) null  ,APPLY_IND VARCHAR(1) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  , primary key(BRANCH,HOLIDAY_TYPE,HOLIDAY_DATE));